Q: Get System Volume iOS A: <p>I did this by initializing an MPVolumeView, and checking the value of its slider (tested in iOS 26):</p>
<pre><code>private lazy var volumeView: MPVolumeView = {
    let view = MPVolumeView(frame: CGRect(x: -1000, y: -1000, width: 0, height: 0))
    view.isHidden = true
    return view
}()
</code></pre>
<pre><code>view.addSubview(volumeView)
guard let slider = self.volumeView.subviews.first(where: { $0 is UISlider }) as? UISlider else {
    return
}
DispatchQueue.main.asyncAfter(deadline: .now() + 1.5) {
    print(&quot;init slider.value: \(slider.value)&quot;)
    BlueTipSoundPlayer.shared.systemVolume = slider.value
}
</code></pre>
